CREATE COLUMN TABLE "TEST_AP"."RDC1" ("DocCode" NVARCHAR(8) NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "DocName" NVARCHAR(64), "LangCode" INTEGER CS_INT NOT NULL , "Template" BLOB MEMORY THRESHOLD 1000, "CreateDate" LONGDATE CS_LONGDATE, "CreateTime" INTEGER CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "UpdateTime" INTEGER CS_INT, PRIMARY KEY ("DocCode", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "RDC1_UniqueIdx" ON "TEST_AP"."RDC1" ( "DocCode" ASC, "LangCode" ASC )